  const getGameContent = (gameId) => {
    return gameContentLibrary[gameId] || { type: "memory", pairs: [] };
  };

  const playGame = (game) => {
    // Check if game requires coins
    if (game.coin_cost > 0) {
      if (playerCoins < game.coin_cost) {
        alert(`❌ Not enough coins! You need ${game.coin_cost} coins but only have ${playerCoins}`);
        return;
      }
    }

    // Load game content
    const gameContent = getGameContent(game.id);
    setActiveGame(game);
    setGameType(gameContent.type);
  };

  const handleGameComplete = (scoreEarned) => {
    if (!activeGame) return;

    // Deduct coins if paid game
    let newCoins = playerCoins;
    if (activeGame.coin_cost > 0) {
      newCoins = playerCoins - activeGame.coin_cost;
    }

    // Add reward coins
    newCoins += activeGame.base_reward;
    setPlayerCoins(newCoins);

    // Update user
    if (user) {
      const updatedUser = { ...user, coins: newCoins };
      localStorage.setItem("user", JSON.stringify(updatedUser));
      setUser(updatedUser);
    }

    // Track progress
    setProgress((prev) => ({
      ...prev,
      [activeGame.id]: (prev[activeGame.id] || 0) + 1,
    }));

    // Notify parent
    if (onGameWin) onGameWin(activeGame.id, activeGame.base_reward);

    // Show completion modal
    alert(`🎉 Great job! You earned ${activeGame.base_reward} coins!`);
    setActiveGame(null);
  };

  const handleExitGame = () => {
    if (window.confirm("Are you sure you want to exit? Your progress will not be saved.")) {
      setActiveGame(null);
    }
  };

  if (isLoading) {
    return <div style={{ padding: "40px", textAlign: "center", color: "white", background: "#0f172a", minHeight: "100vh" }}>
      <h1>Loading games...</h1>
    </div>;
  }

  if (!user) {
    return <div style={{ padding: "40px", textAlign: "center", color: "white", background: "#0f172a", minHeight: "100vh" }}>
      <h1>⚠️ Please log in to play games</h1>
      <p>Redirect to login...</p>
    </div>;
  }

  // If a game is active, show the game interface
  if (activeGame && gameType) {
    const gameContent = getGameContent(activeGame.id);

    return (
      <section style={{ padding: "40px 20px", minHeight: "100vh", background: "#0f172a", color: "white" }}>
        {gameType === "matching" && (
          <MatchingGame
            gameData={{ ...activeGame, ...gameContent }}
            onComplete={handleGameComplete}
            onExit={handleExitGame}
          />
        )}
        {gameType === "quiz" && (
          <QuizGame
            gameData={{ ...activeGame, ...gameContent }}
            onComplete={handleGameComplete}
            onExit={handleExitGame}
          />
        )}
        {gameType === "puzzle" && (
          <PuzzleGame
            gameData={{ ...activeGame, ...gameContent }}
            onComplete={handleGameComplete}
            onExit={handleExitGame}
          />
        )}
      </section>
    );
  }

  return (
    <section style={{ padding: "40px 20px", minHeight: "100vh", background: "#0f172a", color: "white" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
        <h1 style={{ textAlign: "center", flex: 1, fontSize: "32px", margin: 0 }}>🎮 Games by Subject</h1>
        <div style={{ fontSize: "18px", fontWeight: "600", color: "#fbbf24", marginRight: "20px" }}>
          💰 {playerCoins} Coins
        </div>
      </div>
      <p style={{ textAlign: "center", marginBottom: "40px", fontSize: "14px", color: "#cbd5e1" }}>Welcome {user?.firstName || "Player"}! Play games to earn coins and master each topic!</p>

      {/* Topic Selection */}
      <div style={{ marginBottom: "32px", display: "flex", gap: "12px", flexWrap: "wrap", justifyContent: "center" }}>
        {Object.keys(gamesByTopic).map((topic) => (
          <button
            key={topic}
            onClick={() => setSelectedTopic(topic)}
            style={{
              padding: "10px 20px",
              borderRadius: "8px",
              border: selectedTopic === topic ? "2px solid #06b6d4" : "2px solid #4b5563",
              backgroundColor: selectedTopic === topic ? "#06b6d4" : "transparent",
              color: "white",
              cursor: "pointer",
              fontSize: "14px",
              fontWeight: selectedTopic === topic ? "700" : "400",
              transition: "all 0.3s ease",
            }}
          >
            {topic}
          </button>
        ))}
      </div>

      {/* Games Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: "20px", maxWidth: "1400px", margin: "0 auto" }}>
        {topicGames.map((game) => {
          const isFree = game.coin_cost === 0;
          const canPlay = isFree || playerCoins >= game.coin_cost;

          return (
            <div key={game.id} style={{ 
              padding: "20px", 
              borderRadius: "12px", 
              border: isFree ? "2px solid #10b981" : canPlay ? "1px solid rgba(99, 102, 241, 0.3)" : "1px solid rgba(239, 68, 68, 0.3)",
              backgroundColor: isFree ? "rgba(16, 185, 129, 0.1)" : canPlay ? "rgba(30, 41, 59, 0.6)" : "rgba(127, 29, 29, 0.2)",
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", marginBottom: "8px" }}>
                <div>
                  <h3 style={{ margin: "0 0 8px 0", fontSize: "18px", color: "#ffffff" }}>{game.title}</h3>
                  <p style={{ fontSize: "12px", color: "#94a3b8", margin: "0 0 4px 0" }}>Lesson: {game.lesson}</p>
                </div>
                <div style={{
                  padding: "4px 12px",
                  borderRadius: "4px",
                  fontSize: "11px",
                  fontWeight: "600",
                  backgroundColor: isFree ? "#10b981" : game.difficulty === "Easy" ? "#06b6d4" : game.difficulty === "Medium" ? "#f59e0b" : game.difficulty === "Hard" ? "#ef4444" : "#a855f7",
                  color: "white",
                  whiteSpace: "nowrap"
                }}>
                  {isFree ? "FREE" : game.difficulty}
                </div>
              </div>

              <p style={{ fontSize: "14px", color: "#cbd5e1", margin: "0 0 16px 0", minHeight: "40px" }}>{game.description}</p>

              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "16px", gap: "12px", fontSize: "13px" }}>
                <div style={{ display: "flex", gap: "12px" }}>
                  {game.coin_cost > 0 && (
                    <div style={{ color: "#fbbf24", fontWeight: "600" }}>
                      💰 {game.coin_cost} to play
                    </div>
                  )}
                  <div style={{ color: "#10b981", fontWeight: "600" }}>
                    ⭐ +{game.base_reward} coins
                  </div>
                </div>
                <button
                  onClick={() => playGame(game)}
                  disabled={!canPlay}
                  style={{
                    padding: "8px 16px",
                    borderRadius: "6px",
                    border: "none",
                    backgroundColor: canPlay ? "#6366f1" : "#6b7280",
                    color: "white",
                    cursor: canPlay ? "pointer" : "not-allowed",
                    fontSize: "14px",
                    fontWeight: "600",
                    transition: "all 0.3s ease",
                    opacity: canPlay ? 1 : 0.6,
                  }}
                  onMouseEnter={(e) => {
                    if (canPlay) {
                      e.target.style.backgroundColor = "#4f46e5";
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (canPlay) {
                      e.target.style.backgroundColor = "#6366f1";
                    }
                  }}
                >
                  {!canPlay ? "🔒 Locked" : progress[game.id] ? `Played ${progress[game.id]}x` : "Play"}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

export default Games;
